import fs from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("submitting a vendor with missing documents", () => {
  test("lists the missing kinds when only a w9 is extracted", { tag: "@REV-02" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const created = await member.post("/api/vendors", {
      data: { name: uniqueName("Missing Docs"), category: "services", contact_email: "billing@missing-docs.example" },
    });
    expect(created.status(), await created.text()).toBe(201);
    const vendor = (await created.json()) as { id: string };

    const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "w9",
        file: {
          name: "w9.txt",
          mimeType: "text/plain",
          buffer: fs.readFileSync(sample("w9.txt")),
        },
      },
    });
    expect(upload.status(), await upload.text()).toBe(201);
    const document = (await upload.json()) as { id: string };

    // Wait for background extraction to finish before submitting.
    await expect
      .poll(
        async () => {
          const res = await member.get(`/api/documents/${document.id}`);
          return ((await res.json()) as { status: string }).status;
        },
        { timeout: 30_000 },
      )
      .toBe("extracted");

    // Act
    const response = await member.post(`/api/vendors/${vendor.id}/submit`);
    const body = await response.text();

    // Assert
    expect(response.status(), body).toBe(409);
    const error = (JSON.parse(body) as { error: { code: string; missing_kinds: string[] } }).error;
    expect(error.code, body).toBe("documents_incomplete");
    expect(error.missing_kinds, body).toEqual(["contract", "insurance_certificate"]);
  });
});
